from collections import deque

def resolve(path, cwd, links):
    max_links = 8
    link_count = 0

    def split(p):
        return [c for c in p.split('/') if c != '' and c != '.']

    if path.startswith('/'):
        current = '/'
        remaining = split(path)
    else:
        current = cwd
        remaining = split(path)

    queue = deque(remaining)

    while queue:
        comp = queue.popleft()
        if comp == '..':
            if current == '/':
                current = '/'
            else:
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
        else:
            if current == '/':
                new_path = '/' + comp
            else:
                new_path = current + '/' + comp

            if new_path in links:
                link_count += 1
                if link_count > max_links:
                    return None
                target = links[new_path]
                if target.startswith('/'):
                    base = '/'
                    target_comps = split(target)
                else:
                    base = current
                    target_comps = split(target)
                # The link resolution continues with target components
                # base is the directory relative to which the target is resolved
                # We need to set current appropriately before processing target components
                current = base
                for c in reversed(target_comps):
                    queue.appendleft(c)
            else:
                current = new_path

    return current

